use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use actix_multipart::Multipart;
use futures_util::StreamExt;
use std::fs;
use std::io::Write;
use std::path::PathBuf;
use zip::ZipArchive;
use tempfile::NamedTempFile;

const UPLOAD_DIR: &str = "/var/app/extracted";

async fn handle_upload(mut payload: Multipart) -> HttpResponse {
    while let Some(Ok(mut field)) = payload.next().await {
        let content_disposition = field.content_disposition();
        let filename = content_disposition
            .get_filename()
            .unwrap_or("upload.zip")
            .to_string();

        // Only accept zip files
        if !filename.ends_with(".zip") {
            return HttpResponse::BadRequest().body("Only .zip files accepted");
        }

        // Write uploaded content to temp file
        let mut temp_file = match NamedTempFile::new() {
            Ok(f) => f,
            Err(_) => return HttpResponse::InternalServerError().finish(),
        };

        while let Some(Ok(chunk)) = field.next().await {
            if temp_file.write_all(&chunk).is_err() {
                return HttpResponse::InternalServerError().finish();
            }
        }

        // Extract zip contents
        let temp_path = temp_file.path().to_owned();
        match extract_zip(&temp_path) {
            Ok(count) => {
                return HttpResponse::Ok().body(format!("Extracted {} files", count));
            }
            Err(e) => {
                return HttpResponse::InternalServerError().body(format!("Extract error: {}", e));
            }
        }
    }
    HttpResponse::BadRequest().body("No file provided")
}

fn extract_zip(zip_path: &std::path::Path) -> Result<usize, Box<dyn std::error::Error>> {
    let file = fs::File::open(zip_path)?;
    let mut archive = ZipArchive::new(file)?;
    let base_path = PathBuf::from(UPLOAD_DIR);
    let mut count = 0;

    for i in 0..archive.len() {
        let mut entry = archive.by_index(i)?;
        let entry_name = entry.name().to_string();

        // Construct output path by joining base with entry name
        // Note: entry_name comes directly from zip metadata
        let out_path = base_path.join(&entry_name);

        // Create parent directories if needed
        if entry.is_dir() {
            fs::create_dir_all(&out_path)?;
        } else {
            if let Some(parent) = out_path.parent() {
                fs::create_dir_all(parent)?;
            }
            let mut outfile = fs::File::create(&out_path)?;
            std::io::copy(&mut entry, &mut outfile)?;
            count += 1;
        }
    }
    Ok(count)
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().body("OK")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    fs::create_dir_all(UPLOAD_DIR).ok();

    HttpServer::new(|| {
        App::new()
            .route("/health", web::get().to(health_check))
            .route("/api/v1/upload", web::post().to(handle_upload))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
